{
  "description": "The creature is shown in side profile facing right against a plain light background. It has a low, elongated quadrupedal body with a broad flat head, four short fleshy limbs, and a long broad tapering tail. The ventral skin and limbs are pale pinkish-gray with wrinkled texture and darker mottling on the head, while the entire dorsal surface from the back of the neck to the tip of the tail is covered in overlapping large brown keratinous scales. Six feathery external gills extend from the sides of the neck behind the head.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat and rounded at the snout, pale pinkish-gray with darker gray mottled spots, small dark eyes on the sides of the head, small nostrils at the tip of the snout, and a thin closed mouth line",
      "where": "at the front right end of the body"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gills, pinkish-red stalks with fine red filamentous branches, three on each side",
      "where": "protruding outward from the neck immediately behind the head, three on the near side and three on the far side"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales in shades of brown with lighter edges and fine striations, arranged in diagonal rows",
      "where": "covering the entire dorsal and lateral surfaces from the back of the neck along the back and over the dorsal side of the tail to the tip"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, fleshy limbs with wrinkled pale pinkish-gray skin and visible folds at the joints",
      "where": "two under the front third of the body and two under the rear third of the body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "small feet with short distinct digits tipped with tiny claws, skin wrinkled and pale",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, broad, dorsoventrally flattened and tapering to a rounded tip, dorsally covered in the same overlapping brown scales and ventrally pale smooth skin with a thin dorsal fin-like ridge along the top midline near the base",
      "where": "extending to the left from the rear of the body"
    },
    {
      "part": "markings",
      "looks_like": "mottled darker gray spots and pale wrinkled transverse folds on the underbelly and throat",
      "where": "on the head, throat, and ventral surface of the body between the limbs"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
